package collection;

import java.util.ArrayList;

public class ForEachLoop {

	public static void main(String[] args) {
		
	ArrayList <String> s=new ArrayList<String>();
	
	s.add("Blue");
	s.add("Black");
	s.add("White");
	System.out.println(s);
	
	for(String b:s)
	{
		
		System.out.println(b);
	}
	
		// TODO Auto-generated method stub

	}

}
